pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(uint256 amount, address user) public {
        vm.assume(address(0) != user && address(0) != address(this));
        vm.assume(amount > 0 && amount < 1e30);
        // Perform a deposit to user first so we have some imBalances
        // We need to simulate a prior deposit to set imBalances[user]
        // Use an intermediate account to deposit
        address depositor = address(0x1234);
        // We cannot directly call supplyTokenTo without the mAsset tokens.
        // Instead, we use the fact that the test itself can hold tokens via mAsset.safeTransferFrom.
        // To avoid token manipulation, we use a simpler approach: we directly set imBalances by calling redeemToken as trusted caller?
        // Since we cannot set imBalances directly, we rely on the fact that after approveMax, the imBalances should be unchanged for any address that hasn't interacted.
        // The general rule: After approveMax, imBalances[user] remains as it was before approveMax.
        // But we need to read imBalances before and after.
        // We'll capture imBalances before, call approveMax, then check it hasn't changed.
        uint256 before = c.imBalances(user);
        c.approveMax();
        uint256 after = c.imBalances(user);
        assertTrue(before == after);
