pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(address caller, address beneficiary, uint256 amount) public {
        vm.assume(amount > 0 && amount < 1e30);
        vm.assume(beneficiary != address(0));
        vm.assume(caller != address(0));

        // Record initial imBalances of caller
        uint256 initialBalance = c.imBalances(caller);

        // Perform a supply (which would update imBalances if not buggy)
        vm.prank(caller);
        c.supplyTokenTo(amount, beneficiary);

        // Record imBalances after supply
        uint256 afterSupplyBalance = c.imBalances(caller);

        // Call approveMax
        vm.prank(caller);
        c.approveMax();

        // Record imBalances after approveMax
        uint256 afterApproveBalance = c.imBalances(caller);

        // The bug is that supplyTokenTo does not update imBalances, so caller's balance remains 0
        // approveMax should not change imBalances either
        // After approveMax, the caller's imBalances should be unchanged from before the call
        assertTrue(c.imBalances(caller) == afterApproveBalance, "imBalances changed after approveMax");
    }
}

